-- CLI-created migration. Current memberships and trusted transactions own team authority.
create schema if not exists private;
revoke all on schema private from public,anon;
grant usage on schema private to authenticated;
create extension if not exists pgcrypto with schema extensions;

create table public.companies(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 120),currency text not null check(currency ~ '^[A-Z]{3}$'),timezone text not null,state text not null default 'active' check(state in ('active','archived')),independent_review boolean not null default true,require_mfa boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.plants(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),name text not null,unique(company_id,id));
create table public.warehouses(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,name text not null,foreign key(company_id,plant_id) references public.plants(company_id,id),unique(company_id,id));
create table public.roles(company_id uuid not null references public.companies(id),name text not null,primary key(company_id,name));
create table public.role_permissions(company_id uuid not null,role_name text not null,permission text not null,primary key(company_id,role_name,permission),foreign key(company_id,role_name) references public.roles(company_id,name));
create table public.memberships(company_id uuid not null references public.companies(id),user_id uuid not null references auth.users(id),active boolean not null default true,all_plants boolean not null default false,created_at timestamptz not null default now(),primary key(company_id,user_id));
create table public.member_role_assignments(company_id uuid not null,user_id uuid not null,role_name text not null,primary key(company_id,user_id,role_name),foreign key(company_id,user_id) references public.memberships(company_id,user_id),foreign key(company_id,role_name) references public.roles(company_id,name));
create table public.member_plant_scopes(company_id uuid not null,user_id uuid not null,plant_id uuid not null,primary key(company_id,user_id,plant_id),foreign key(company_id,user_id) references public.memberships(company_id,user_id),foreign key(company_id,plant_id) references public.plants(company_id,id));
create table private.invitations(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),email text not null,token_hash text not null unique,roles text[] not null,plant_ids uuid[] not null,all_plants boolean not null,inviter uuid not null references auth.users(id),expires_at timestamptz not null,accepted_at timestamptz);
create table private.ownership_transfers(company_id uuid primary key references public.companies(id),from_user uuid not null references auth.users(id),to_user uuid not null references auth.users(id),created_at timestamptz not null default now());
create table private.request_results(scope text not null,actor uuid not null references auth.users(id),command text not null,request_key uuid not null,fingerprint text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(scope,actor,command,request_key));
create table public.records(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,kind text not null check(kind in ('customer','supplier','item','engineering','rfq','quotation','sales_order','purchase_order','work_order','equipment','ncr','jobwork')),code text not null check(length(code) between 1 and 80),name text not null check(length(name) between 1 and 200),state text not null,revision bigint not null default 1,fields jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(company_id,plant_id) references public.plants(company_id,id),unique(company_id,kind,code),unique(company_id,plant_id,id));
create table public.stock_lots(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,item_id uuid not null,code text not null,location text not null,qc_state text not null default 'held' check(qc_state in ('held','released')),revision bigint not null default 1,foreign key(company_id,plant_id,item_id) references public.records(company_id,plant_id,id),unique(company_id,code),unique(company_id,plant_id,id));
create table public.stock_ledger_entries(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,lot_id uuid not null,quantity numeric(30,6) not null check(quantity<>0),custody text not null check(custody in ('stores','wip','vendor','consumed','shipped','loss')),reference_id uuid not null,event text not null,created_at timestamptz not null default now(),foreign key(company_id,plant_id,lot_id) references public.stock_lots(company_id,plant_id,id));
create table public.stock_reservations(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,lot_id uuid not null,order_id uuid not null,quantity numeric(30,6) not null check(quantity>0),state text not null default 'active' check(state in ('active','released','dispatched')),foreign key(company_id,plant_id,lot_id) references public.stock_lots(company_id,plant_id,id),foreign key(company_id,plant_id,order_id) references public.records(company_id,plant_id,id),unique(company_id,plant_id,id));
create table public.inspections(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,lot_id uuid not null,lot_revision bigint not null,lower_limit numeric(30,6) not null,upper_limit numeric(30,6) not null,readings jsonb not null,unit text not null,passed boolean not null,inspector uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(company_id,plant_id,lot_id) references public.stock_lots(company_id,plant_id,id));
create table public.packages(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,code text not null,reservation_id uuid not null,lot_id uuid not null,order_id uuid not null,quantity numeric(30,6) not null check(quantity>0),state text not null default 'verified' check(state in ('verified','dispatched')),foreign key(company_id,plant_id,reservation_id) references public.stock_reservations(company_id,plant_id,id),foreign key(company_id,plant_id,lot_id) references public.stock_lots(company_id,plant_id,id),foreign key(company_id,plant_id,order_id) references public.records(company_id,plant_id,id),unique(company_id,plant_id,id),unique(reservation_id));
create table public.shipments(id uuid primary key default gen_random_uuid(),company_id uuid not null,plant_id uuid not null,code text not null,package_id uuid not null unique,lot_id uuid not null,order_id uuid not null,quantity numeric(30,6) not null check(quantity>0),carrier text not null,created_at timestamptz not null default now(),foreign key(company_id,plant_id,package_id) references public.packages(company_id,plant_id,id),foreign key(company_id,plant_id,lot_id) references public.stock_lots(company_id,plant_id,id),foreign key(company_id,plant_id,order_id) references public.records(company_id,plant_id,id),unique(company_id,plant_id,id));
create table public.audit_log(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),plant_id uuid,command text not null,entity_id uuid not null,actor uuid not null references auth.users(id),reason text not null default '',created_at timestamptz not null default now());
create index membership_actor_idx on public.memberships(user_id,company_id) where active;
create index permission_lookup_idx on public.role_permissions(company_id,permission,role_name);
create index records_scope_idx on public.records(company_id,plant_id,kind,created_at);
create index ledger_balance_idx on public.stock_ledger_entries(company_id,plant_id,lot_id,custody);
create index reservations_scope_idx on public.stock_reservations(company_id,plant_id,lot_id) where state='active';

create function private.reject_change() returns trigger language plpgsql set search_path='' as $$begin raise exception 'APPEND_ONLY'; end$$;
create trigger ledger_append_only before update or delete on public.stock_ledger_entries for each row execute function private.reject_change();
create trigger audit_append_only before update or delete on public.audit_log for each row execute function private.reject_change();
create function private.engineering_immutable() returns trigger language plpgsql set search_path='' as $$begin if old.kind='engineering' and old.state='approved' then raise exception 'IMMUTABLE_REVISION';end if;return new;end$$;
create trigger engineering_immutable before update or delete on public.records for each row execute function private.engineering_immutable();
create function private.member(company uuid,plant uuid default null) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.company_id=company and m.user_id=(select auth.uid()) and m.active and (plant is null or m.all_plants or exists(select 1 from public.member_plant_scopes p where p.company_id=m.company_id and p.user_id=m.user_id and p.plant_id=plant)))$$;
create function private.has_permission(company uuid,permission_key text,plant uuid default null) returns boolean language sql stable security definer set search_path='' as $$select private.member(company,plant) and exists(select 1 from public.member_role_assignments a join public.role_permissions p on p.company_id=a.company_id and p.role_name=a.role_name where a.company_id=company and a.user_id=(select auth.uid()) and p.permission=permission_key)$$;
create function private.require_permission(company uuid,permission_key text,plant uuid default null) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;if not private.has_permission(company,permission_key,plant) then raise exception 'PERMISSION_DENIED';end if;if not exists(select 1 from public.companies c where c.id=company and c.state='active') then raise exception 'INVALID_TRANSITION';end if;if exists(select 1 from public.companies c where c.id=company and c.require_mfa) and permission_key not like '%.read' and coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception 'AUTH_REQUIRED';end if;end$$;
create function private.audit(company uuid,plant uuid,action text,entity uuid,reason text default '') returns void language sql security definer set search_path='' as $$insert into public.audit_log(company_id,plant_id,command,entity_id,actor,reason)values(company,plant,action,entity,auth.uid(),reason)$$;
create function private.decimal(value text) returns numeric language plpgsql immutable set search_path='' as $$begin if value is null or value !~ '^(0|[1-9][0-9]{0,23})(\.[0-9]{1,6})?$' then raise exception 'INVALID_INPUT';end if;return value::numeric;end$$;
create function private.decimal_text(value numeric) returns text language sql immutable set search_path='' as $$select case when position('.' in value::text)>0 then rtrim(rtrim(value::text,'0'),'.') else value::text end$$;
create function private.balance(company uuid,plant uuid,lot uuid,custody_key text default 'stores') returns numeric language sql stable security definer set search_path='' as $$select coalesce(sum(quantity),0)from public.stock_ledger_entries where company_id=company and plant_id=plant and lot_id=lot and custody=custody_key$$;
create function private.reserved(company uuid,plant uuid,lot uuid) returns numeric language sql stable security definer set search_path='' as $$select coalesce(sum(quantity),0)from public.stock_reservations where company_id=company and plant_id=plant and lot_id=lot and state='active'$$;
create function private.record_read_permission(kind text) returns text language sql immutable set search_path='' as $$select case when kind in ('rfq','quotation','sales_order') then 'sales.read' when kind='work_order' then 'production.read' when kind='ncr' then 'quality.read' when kind='purchase_order' then 'procurement.manage' when kind='jobwork' then 'jobwork.manage' else 'master_data.read' end$$;

alter table public.companies enable row level security;
create policy companies_read on public.companies for select to authenticated using(private.member(id));
alter table public.plants enable row level security;
create policy plants_read on public.plants for select to authenticated using(private.member(company_id,id));
alter table public.warehouses enable row level security;
create policy warehouses_read on public.warehouses for select to authenticated using(private.member(company_id,plant_id));
alter table public.roles enable row level security;
create policy roles_read on public.roles for select to authenticated using(private.has_permission(company_id,'roles.assign'));
alter table public.role_permissions enable row level security;
create policy role_permissions_read on public.role_permissions for select to authenticated using(private.has_permission(company_id,'roles.assign'));
alter table public.memberships enable row level security;
create policy memberships_read on public.memberships for select to authenticated using(private.member(company_id) and (user_id=auth.uid() or private.has_permission(company_id,'members.manage')));
alter table public.member_role_assignments enable row level security;
create policy member_roles_read on public.member_role_assignments for select to authenticated using(private.member(company_id) and (user_id=auth.uid() or private.has_permission(company_id,'members.manage')));
alter table public.member_plant_scopes enable row level security;
create policy member_plants_read on public.member_plant_scopes for select to authenticated using(private.member(company_id) and (user_id=auth.uid() or private.has_permission(company_id,'members.manage')));
alter table public.records enable row level security;
create policy records_read on public.records for select to authenticated using(private.has_permission(company_id,private.record_read_permission(kind),plant_id) and (kind<>'work_order' or private.has_permission(company_id,'production.assign',plant_id) or coalesce(fields->>'assignedUserId','')=auth.uid()::text));
alter table public.stock_lots enable row level security;
create policy lots_read on public.stock_lots for select to authenticated using(private.has_permission(company_id,'stock.read',plant_id));
alter table public.stock_ledger_entries enable row level security;
create policy ledger_read on public.stock_ledger_entries for select to authenticated using(private.has_permission(company_id,'stock.read',plant_id));
alter table public.stock_reservations enable row level security;
create policy reservations_read on public.stock_reservations for select to authenticated using(private.has_permission(company_id,'stock.read',plant_id));
alter table public.inspections enable row level security;
create policy inspections_read on public.inspections for select to authenticated using(private.has_permission(company_id,'quality.read',plant_id));
alter table public.packages enable row level security;
create policy packages_read on public.packages for select to authenticated using(private.has_permission(company_id,'dispatch.manage',plant_id));
alter table public.shipments enable row level security;
create policy shipments_read on public.shipments for select to authenticated using(private.has_permission(company_id,'sales.read',plant_id));
alter table public.audit_log enable row level security;
create policy audit_read on public.audit_log for select to authenticated using(private.has_permission(company_id,'audit.read',plant_id));
revoke all on all tables in schema public from anon,authenticated;
grant select on public.companies,public.plants,public.warehouses,public.roles,public.role_permissions,public.memberships,public.member_role_assignments,public.member_plant_scopes,public.records,public.stock_lots,public.stock_ledger_entries,public.stock_reservations,public.inspections,public.packages,public.shipments,public.audit_log to authenticated;
revoke all on all tables in schema private from public,anon,authenticated;

create function private.create_company(input jsonb,request_key uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();company uuid;plant uuid;fingerprint text:=md5(input::text);previous private.request_results%rowtype;template jsonb;entry record;
begin
 if v_actor is null or not exists(select 1 from auth.users where id=v_actor and email_confirmed_at is not null)then raise exception 'AUTH_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':create_company',0));
 select * into previous from private.request_results where scope='account' and actor=v_actor and command='create_company' and request_results.request_key=create_company.request_key;
 if found then if previous.fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_KEY_REUSED';end if;return (previous.result->>'id')::uuid;end if;
 if (select count(*)from public.companies where created_by=v_actor and created_at>now()-interval '1 hour')>=5 then raise exception 'INVALID_INPUT';end if;
 if input->>'name' is null or input->>'currency' !~ '^[A-Z]{3}$' or not exists(select 1 from pg_timezone_names where name=input->>'timezone')or length(coalesce(input->>'plantName',''))=0 or length(coalesce(input->>'warehouseName',''))=0 then raise exception 'INVALID_INPUT';end if;
 insert into public.companies(name,currency,timezone,created_by)values(trim(input->>'name'),input->>'currency',input->>'timezone',v_actor)returning id into company;
 insert into public.plants(company_id,name)values(company,input->>'plantName')returning id into plant;
 insert into public.warehouses(company_id,plant_id,name)values(company,plant,input->>'warehouseName');
 -- Role mapping is generated from the shared protected templates before migration application.
 template:='{"Owner":["company.manage","plants.manage","members.invite","members.manage","roles.assign","company.transfer_owner","company.archive","master_data.read","master_data.manage","engineering.approve","sales.read","sales.manage","commercial.approve","planning.manage","procurement.manage","procurement.approve","stock.read","stock.receive","stock.reserve","stock.issue","stock.transfer","stock.count","stock.review_count","production.read","production.execute","production.assign","quality.read","quality.inspect","quality.review","jobwork.manage","dispatch.manage","dispatch.confirm","equipment.manage","documents.read","documents.manage","reports.read","accounting.export","audit.read","data_transfer.manage"],"Administrator":["company.manage","plants.manage","members.invite","members.manage","roles.assign","master_data.read","master_data.manage","documents.read","audit.read"],"Management":["master_data.read","sales.read","stock.read","production.read","quality.read","reports.read","commercial.approve","documents.read"],"Sales":["master_data.read","sales.read","sales.manage","documents.read"],"Engineering":["master_data.read","master_data.manage","documents.read","documents.manage"],"Costing/Commercial":["master_data.read","sales.read","sales.manage","commercial.approve"],"Planning":["master_data.read","sales.read","stock.read","planning.manage","production.read","reports.read"],"Purchasing":["master_data.read","procurement.manage","documents.read"],"Stores":["master_data.read","stock.read","stock.receive","stock.reserve","stock.issue","stock.transfer","stock.count","documents.read"],"Production supervisor":["master_data.read","stock.read","production.read","production.execute","production.assign","equipment.manage"],"Operator":["production.read","production.execute"],"Quality inspector":["master_data.read","stock.read","quality.read","quality.inspect","documents.read"],"Quality reviewer":["master_data.read","stock.read","quality.read","quality.review","documents.read"],"Subcontract coordinator":["master_data.read","stock.read","jobwork.manage","documents.read"],"Packing/Dispatch":["master_data.read","stock.read","sales.read","dispatch.manage","dispatch.confirm","documents.read"],"Accounts":["sales.read","accounting.export","reports.read"],"Auditor":["master_data.read","sales.read","stock.read","production.read","quality.read","reports.read","audit.read"]}'::jsonb;
 for entry in select key,value from jsonb_each(template)loop
  insert into public.roles values(company,entry.key);
  insert into public.role_permissions select company,entry.key,jsonb_array_elements_text(entry.value);
 end loop;
 insert into public.memberships(company_id,user_id,all_plants)values(company,v_actor,true);
 insert into public.member_role_assignments values(company,v_actor,'Owner');
 perform private.audit(company,plant,'create_company',company,'Verified creator becomes Owner');
 insert into private.request_results(scope,actor,command,request_key,fingerprint,result)values('account',v_actor,'create_company',request_key,fingerprint,jsonb_build_object('id',company));return company;
end$$;
create function public.create_company(input jsonb,request_key uuid)returns uuid language sql security invoker set search_path='' as $$select private.create_company(input,request_key)$$;
create function public.list_workspaces()returns jsonb language sql security invoker set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'currency',currency,'timezone',timezone,'createdAt',created_at)order by created_at),'[]')from public.companies$$;

create function private.check_delegation(company uuid,desired_roles text[],desired_plants uuid[],all_plants boolean)returns void language plpgsql security definer set search_path='' as $$begin
 if array_length(desired_roles,1)is null or 'Owner'=any(desired_roles)or exists(select 1 from unnest(desired_roles)r where not exists(select 1 from public.roles where company_id=company and name=r))then raise exception 'PERMISSION_DENIED';end if;
 if exists(select 1 from public.role_permissions p where p.company_id=company and p.role_name=any(desired_roles)and not private.has_permission(company,p.permission))then raise exception 'PERMISSION_DENIED';end if;
 if all_plants and not exists(select 1 from public.memberships where company_id=company and user_id=auth.uid()and memberships.all_plants)then raise exception 'PERMISSION_DENIED';end if;
 if exists(select 1 from unnest(desired_plants)p where not exists(select 1 from public.plants where company_id=company and id=p)or not private.member(company,p))then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
 if not all_plants and coalesce(array_length(desired_plants,1),0)=0 then raise exception 'INVALID_INPUT';end if;
end$$;
create function private.invite_member(company uuid,email text,desired_roles text[],desired_plants uuid[],all_plants boolean,request_key uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare token text:=gen_random_uuid()::text;invitation uuid;fingerprint text:=md5(jsonb_build_array(lower(trim(email)),desired_roles,desired_plants,all_plants)::text);previous private.request_results%rowtype;begin
 perform private.require_permission(company,'members.invite');perform private.check_delegation(company,desired_roles,desired_plants,all_plants);
 perform pg_advisory_xact_lock(hashtextextended(company::text||auth.uid()::text||request_key::text,0));
 select * into previous from private.request_results where scope=company::text and actor=auth.uid()and command='invite_member'and request_results.request_key=invite_member.request_key;
 if found then if previous.fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_KEY_REUSED';end if;return previous.result;end if;
 if email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'then raise exception 'INVALID_INPUT';end if;
 insert into private.invitations(company_id,email,token_hash,roles,plant_ids,all_plants,inviter,expires_at)values(company,lower(trim(email)),encode(extensions.digest(token,'sha256'),'hex'),desired_roles,desired_plants,all_plants,auth.uid(),now()+interval '7 days')returning id into invitation;
 perform private.audit(company,null,'invite_member',invitation,'Invitation created; external delivery is explicit');
 insert into private.request_results(scope,actor,command,request_key,fingerprint,result)values(company::text,auth.uid(),'invite_member',request_key,fingerprint,jsonb_build_object('id',invitation,'token',token));return jsonb_build_object('id',invitation,'token',token);
end$$;
create function public.invite_member(company uuid,email text,desired_roles text[],desired_plants uuid[],all_plants boolean,request_key uuid)returns jsonb language sql security invoker set search_path=''as $$select private.invite_member(company,email,desired_roles,desired_plants,all_plants,request_key)$$;
create function private.accept_invitation(token text)returns uuid language plpgsql security definer set search_path=''as $$declare invitation private.invitations%rowtype;actor uuid:=auth.uid();email text;begin
 select users.email into email from auth.users where id=actor and email_confirmed_at is not null;if email is null then raise exception 'AUTH_REQUIRED';end if;
 select * into invitation from private.invitations where token_hash=encode(extensions.digest(token,'sha256'),'hex')for update;
 if not found or invitation.email<>lower(email)or invitation.expires_at<=now()then raise exception 'PERMISSION_DENIED';end if;
 if invitation.accepted_at is not null then if exists(select 1 from public.memberships where company_id=invitation.company_id and user_id=actor and active)then return invitation.company_id;end if;raise exception 'PERMISSION_DENIED';end if;
 if not exists(select 1 from public.companies where id=invitation.company_id and state='active')or not exists(select 1 from public.memberships where company_id=invitation.company_id and user_id=invitation.inviter and active)then raise exception 'PERMISSION_DENIED';end if;
 if not exists(select 1 from public.member_role_assignments a join public.role_permissions p on p.company_id=a.company_id and p.role_name=a.role_name where a.company_id=invitation.company_id and a.user_id=invitation.inviter and p.permission='members.invite')then raise exception 'PERMISSION_DENIED';end if;
 if exists(select 1 from public.role_permissions desired where desired.company_id=invitation.company_id and desired.role_name=any(invitation.roles)and not exists(select 1 from public.member_role_assignments a join public.role_permissions p on p.company_id=a.company_id and p.role_name=a.role_name where a.company_id=desired.company_id and a.user_id=invitation.inviter and p.permission=desired.permission))then raise exception 'PERMISSION_DENIED';end if;
 insert into public.memberships(company_id,user_id,all_plants)values(invitation.company_id,actor,invitation.all_plants)on conflict(company_id,user_id)do update set active=true,all_plants=excluded.all_plants;
 delete from public.member_role_assignments where company_id=invitation.company_id and user_id=actor;
 insert into public.member_role_assignments select invitation.company_id,actor,unnest(invitation.roles);
 delete from public.member_plant_scopes where company_id=invitation.company_id and user_id=actor;
 insert into public.member_plant_scopes select invitation.company_id,actor,unnest(invitation.plant_ids);
 update private.invitations set accepted_at=now()where id=invitation.id;perform private.audit(invitation.company_id,null,'accept_invitation',actor,'Verified matching email');return invitation.company_id;
end$$;
create function public.accept_invitation(token text)returns uuid language sql security invoker set search_path=''as $$select private.accept_invitation(token)$$;
create function private.assign_member_roles(company uuid,member uuid,desired_roles text[],desired_plants uuid[],all_plants boolean,active boolean)returns void language plpgsql security definer set search_path=''as $$begin
 perform private.require_permission(company,'members.manage');perform private.require_permission(company,'roles.assign');perform 1 from public.companies where id=company for update;
 if exists(select 1 from public.member_role_assignments where company_id=company and user_id=member and role_name='Owner')then raise exception 'PERMISSION_DENIED';end if;
 if not exists(select 1 from public.memberships where company_id=company and user_id=member)then raise exception 'INVALID_INPUT';end if;
 perform private.check_delegation(company,desired_roles,desired_plants,all_plants);
 update public.memberships set active=assign_member_roles.active,all_plants=assign_member_roles.all_plants where company_id=company and user_id=member;
 delete from public.member_role_assignments where company_id=company and user_id=member;insert into public.member_role_assignments select company,member,unnest(desired_roles);
 delete from public.member_plant_scopes where company_id=company and user_id=member;insert into public.member_plant_scopes select company,member,unnest(desired_plants);
 perform private.audit(company,null,'assign_member_roles',member,'Current scoped roles changed');
end$$;
create function public.assign_member_roles(company uuid,member uuid,desired_roles text[],desired_plants uuid[],all_plants boolean,active boolean)returns void language sql security invoker set search_path=''as $$select private.assign_member_roles(company,member,desired_roles,desired_plants,all_plants,active)$$;
create function private.manage_company(company uuid,action text,target uuid default null,enabled boolean default null)returns void language plpgsql security definer set search_path=''as $$declare transfer private.ownership_transfers%rowtype;begin
 perform 1 from public.companies where id=company for update;
 if action='accept_transfer'then
  select * into transfer from private.ownership_transfers where company_id=company;
  if not found or transfer.to_user<>auth.uid()or not private.member(company)or not exists(select 1 from auth.users where id=auth.uid()and email_confirmed_at is not null)or not exists(select 1 from public.member_role_assignments where company_id=company and user_id=transfer.from_user and role_name='Owner')then raise exception 'PERMISSION_DENIED';end if;
  insert into public.member_role_assignments values(company,auth.uid(),'Owner')on conflict do nothing;update public.memberships set all_plants=true where company_id=company and user_id=auth.uid();delete from public.member_role_assignments where company_id=company and user_id=transfer.from_user and role_name='Owner';delete from private.ownership_transfers where company_id=company;
 else
  perform private.require_permission(company,case when action='archive'then 'company.archive'else 'company.transfer_owner'end);
  if action='request_transfer'then if target=auth.uid()or not exists(select 1 from public.memberships m join auth.users u on u.id=m.user_id where m.company_id=company and m.user_id=target and m.active and u.email_confirmed_at is not null)then raise exception 'INVALID_INPUT';end if;insert into private.ownership_transfers(company_id,from_user,to_user)values(company,auth.uid(),target)on conflict(company_id)do update set from_user=excluded.from_user,to_user=excluded.to_user,created_at=now();
  elsif action='archive'then update public.companies set state='archived'where id=company;
  elsif action='independent_review'then update public.companies set independent_review=enabled where id=company;
  elsif action='require_mfa'then if coalesce(auth.jwt()->>'aal','aal1')<>'aal2'then raise exception 'AUTH_REQUIRED';end if;update public.companies set require_mfa=enabled where id=company;
  else raise exception 'INVALID_INPUT';end if;
 end if;
 perform private.audit(company,null,action,coalesce(target,company),'Owner-controlled company operation');
end$$;
create function public.manage_company(company uuid,action text,target uuid default null,enabled boolean default null)returns void language sql security invoker set search_path=''as $$select private.manage_company(company,action,target,enabled)$$;

revoke all on all functions in schema private from public,anon,authenticated;
grant execute on function private.member(uuid,uuid),private.has_permission(uuid,text,uuid),private.record_read_permission(text)to authenticated;
grant execute on function private.create_company(jsonb,uuid),private.invite_member(uuid,text,text[],uuid[],boolean,uuid),private.accept_invitation(text),private.assign_member_roles(uuid,uuid,text[],uuid[],boolean,boolean),private.manage_company(uuid,text,uuid,boolean)to authenticated;
revoke all on function public.create_company(jsonb,uuid),public.list_workspaces(),public.invite_member(uuid,text,text[],uuid[],boolean,uuid),public.accept_invitation(text),public.assign_member_roles(uuid,uuid,text[],uuid[],boolean,boolean),public.manage_company(uuid,text,uuid,boolean)from public,anon;
grant execute on function public.create_company(jsonb,uuid),public.list_workspaces(),public.invite_member(uuid,text,text[],uuid[],boolean,uuid),public.accept_invitation(text),public.assign_member_roles(uuid,uuid,text[],uuid[],boolean,boolean),public.manage_company(uuid,text,uuid,boolean)to authenticated;

create function private.validate_fields(kind text,fields jsonb,company uuid,plant uuid)returns void language plpgsql security definer set search_path=''as $$
declare definitions jsonb:='{"customer":[{"key":"reference","label":"Customer reference","type":"text"}],"supplier":[{"key":"reference","label":"Supplier reference","type":"text"}],"item":[{"key":"unit","label":"Base unit","type":"text","required":true,"default":"pcs"},{"key":"grade","label":"Material / grade","type":"text"},{"key":"finish","label":"Finish","type":"text"}],"engineering":[{"key":"itemId","label":"Output item","type":"item","required":true},{"key":"drawingReference","label":"Drawing revision reference","type":"text","required":true},{"key":"route","label":"Operation sequence","type":"text","required":true},{"key":"outputBasis","label":"Output basis","type":"decimal","required":true,"default":"1"}],"rfq":[{"key":"customerId","label":"Customer","type":"customer","required":true},{"key":"itemId","label":"Requested item","type":"item","required":true},{"key":"quantity","label":"Requested quantity","type":"decimal","required":true},{"key":"dueDate","label":"Required date","type":"date","required":true}],"quotation":[{"key":"customerId","label":"Customer","type":"customer","required":true},{"key":"engineeringId","label":"Engineering revision","type":"engineering","required":true},{"key":"quantity","label":"Quantity","type":"decimal","required":true},{"key":"unitPrice","label":"Unit price","type":"decimal","required":true},{"key":"materialCost","label":"Material cost","type":"decimal","default":"0"},{"key":"processCost","label":"Process cost","type":"decimal","default":"0"}],"sales_order":[{"key":"customerId","label":"Customer","type":"customer","required":true},{"key":"quotationId","label":"Approved quotation","type":"quotation","required":true},{"key":"engineeringId","label":"Engineering revision","type":"engineering","required":true},{"key":"itemId","label":"Item","type":"item","required":true},{"key":"quantity","label":"Ordered quantity","type":"decimal","required":true},{"key":"dueDate","label":"Delivery date","type":"date","required":true},{"key":"poReference","label":"Customer PO reference","type":"text","required":true},{"key":"poDiscrepancies","label":"Unresolved PO discrepancies","type":"text"}],"purchase_order":[{"key":"supplierId","label":"Supplier","type":"supplier","required":true},{"key":"itemId","label":"Item","type":"item","required":true},{"key":"quantity","label":"Ordered quantity","type":"decimal","required":true},{"key":"unitPrice","label":"Unit price","type":"decimal","required":true},{"key":"dueDate","label":"Expected date","type":"date","required":true}],"work_order":[{"key":"orderId","label":"Sales order","type":"sales_order","required":true},{"key":"engineeringId","label":"Approved engineering","type":"engineering","required":true},{"key":"itemId","label":"Output item","type":"item","required":true},{"key":"quantity","label":"Planned output","type":"decimal","required":true},{"key":"equipmentId","label":"Required equipment","type":"equipment","required":true}],"equipment":[{"key":"calibrationDue","label":"Calibration valid until","type":"date","required":true}],"ncr":[{"key":"lotId","label":"Affected lot","type":"lot","required":true},{"key":"quantity","label":"Affected quantity","type":"decimal","required":true},{"key":"defect","label":"Defect / containment","type":"text","required":true},{"key":"disposition","label":"Disposition / execution evidence","type":"text"}],"jobwork":[{"key":"supplierId","label":"Supplier","type":"supplier","required":true},{"key":"itemId","label":"Item","type":"item","required":true},{"key":"quantity","label":"Planned quantity","type":"decimal","required":true},{"key":"dueDate","label":"Expected return","type":"date","required":true}]}'::jsonb;field jsonb;value text;entry record;
begin
 if jsonb_typeof(fields)<>'object'or definitions->kind is null then raise exception 'INVALID_INPUT';end if;
 for entry in select key,value from jsonb_each(fields)loop if jsonb_typeof(entry.value)<>'string'or length(entry.value#>>'{}')>4000 or not exists(select 1 from jsonb_array_elements(definitions->kind)f where f->>'key'=entry.key)then raise exception 'INVALID_INPUT';end if;end loop;
 for field in select * from jsonb_array_elements(definitions->kind)loop
  value:=fields->>(field->>'key');
  if coalesce((field->>'required')::boolean,false)and length(coalesce(trim(value),''))=0 then raise exception 'INVALID_INPUT';end if;
  if length(coalesce(value,''))=0 then continue;end if;
  if field->>'type'='decimal'then perform private.decimal(value);if field->>'key'in('quantity','outputBasis')and private.decimal(value)<=0 then raise exception 'INVALID_INPUT';end if;
  elsif field->>'type'='date'then if value !~ '^\d{4}-\d{2}-\d{2}$'or to_char(to_date(value,'YYYY-MM-DD'),'YYYY-MM-DD')<>value then raise exception 'INVALID_INPUT';end if;
  elsif field->>'type'='lot'then if not exists(select 1 from public.stock_lots where company_id=company and plant_id=plant and id=value::uuid)then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
  elsif field->>'type'<>'text'then if not exists(select 1 from public.records where company_id=company and plant_id=plant and id=value::uuid and records.kind=field->>'type')then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
  end if;
 end loop;
end$$;
create function private.command_permission(command text,payload jsonb)returns text language sql immutable set search_path=''as $$select case command
 when 'save_record'then case payload->>'kind'when 'rfq'then 'sales.manage'when 'quotation'then 'sales.manage'when 'sales_order'then 'sales.manage'when 'purchase_order'then 'procurement.manage'when 'work_order'then 'planning.manage'when 'equipment'then 'equipment.manage'when 'ncr'then 'quality.inspect'when 'jobwork'then 'jobwork.manage'else 'master_data.manage'end
 when 'transition_record'then 'master_data.read'
 when 'receive_goods'then 'stock.receive'when 'record_inspection'then 'quality.inspect'when 'release_lot'then 'quality.review'when 'hold_lot'then 'quality.review'when 'reserve_stock'then 'stock.reserve'when 'release_reservation'then 'stock.reserve'when 'verify_packing'then 'dispatch.manage'when 'confirm_dispatch'then 'dispatch.confirm'when 'receive_customer_return'then 'stock.receive'else 'UNIMPLEMENTED'end$$;
create function private.new_lot(company uuid,plant uuid,item uuid,location text)returns uuid language plpgsql security definer set search_path=''as $$declare lot uuid:=gen_random_uuid();begin if length(location)not between 1 and 80 then raise exception 'INVALID_INPUT';end if;insert into public.stock_lots(id,company_id,plant_id,item_id,code,location)values(lot,company,plant,item,'LOT-'||upper(substr(lot::text,1,8)),location);return lot;end$$;
create function private.ledger(company uuid,plant uuid,lot uuid,quantity numeric,custody text,reference uuid,event text)returns void language sql security definer set search_path=''as $$insert into public.stock_ledger_entries(company_id,plant_id,lot_id,quantity,custody,reference_id,event)values(company,plant,lot,quantity,custody,reference,event)$$;
create function private.transition(company uuid,plant uuid,record_id uuid,next_state text,reason text)returns void language plpgsql security definer set search_path=''as $$
declare row public.records%rowtype;engineering public.records%rowtype;quotation public.records%rowtype;allowed jsonb:='{"customer":{"active":["inactive"],"inactive":["active"]},"supplier":{"active":["inactive"],"inactive":["active"]},"item":{"active":["inactive"],"inactive":["active"]},"engineering":{"draft":["approved"],"approved":[]},"rfq":{"draft":["qualified","cancelled"],"qualified":["quoted","cancelled"],"quoted":["converted","lost"],"converted":[],"lost":[],"cancelled":[]},"quotation":{"draft":["pending_approval"],"pending_approval":["approved","draft"],"approved":["sent","superseded"],"sent":["accepted","rejected","expired"],"accepted":[],"rejected":[],"expired":[],"superseded":[]},"sales_order":{"draft":["accepted","cancelled"],"accepted":["closed","cancelled"],"partially_fulfilled":["closed"],"fulfilled":["closed"],"closed":[],"cancelled":[]},"purchase_order":{"draft":["pending_approval","cancelled"],"pending_approval":["open","draft"],"open":["closed","cancelled"],"partial_receipt":["closed"],"received":["closed"],"closed":[],"cancelled":[]},"work_order":{"draft":["released","cancelled"],"released":["in_progress","blocked","cancelled"],"in_progress":["blocked","completed"],"blocked":["in_progress"],"completed":["closed"],"closed":[],"cancelled":[]},"equipment":{"ready":["maintenance","unavailable"],"maintenance":["ready","unavailable"],"unavailable":["ready","maintenance"]},"ncr":{"open":["awaiting_execution"],"awaiting_execution":["closed"],"closed":[]},"jobwork":{"draft":["open","cancelled"],"open":["closed"],"closed":[],"cancelled":[]}}'::jsonb;permission_key text;
begin
 select * into row from public.records where company_id=company and plant_id=plant and id=record_id for update;if not found then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
 if not coalesce((allowed->row.kind->row.state)?next_state,false)then raise exception 'INVALID_TRANSITION';end if;
 permission_key:=case row.kind when 'engineering'then 'engineering.approve'when 'quotation'then case when next_state='approved'then 'commercial.approve'else 'sales.manage'end when 'sales_order'then 'sales.manage'when 'purchase_order'then case when next_state='open'then 'procurement.approve'else 'procurement.manage'end when 'work_order'then 'planning.manage'when 'equipment'then 'equipment.manage'when 'ncr'then 'quality.review'when 'jobwork'then 'jobwork.manage'else 'master_data.manage'end;
 perform private.require_permission(company,permission_key,plant);
 if row.kind='quotation'and next_state='approved'then if not exists(select 1 from public.records where company_id=company and plant_id=plant and id=(row.fields->>'engineeringId')::uuid and kind='engineering'and state='approved')then raise exception 'INVALID_TRANSITION';end if;end if;
 if row.kind='sales_order'and next_state='accepted'then
  select * into engineering from public.records where company_id=company and plant_id=plant and id=(row.fields->>'engineeringId')::uuid and kind='engineering';
  select * into quotation from public.records where company_id=company and plant_id=plant and id=(row.fields->>'quotationId')::uuid and kind='quotation';
  if engineering.state is distinct from 'approved'or quotation.state not in('approved','sent','accepted')or quotation.fields->>'engineeringId'<>engineering.id::text or quotation.fields->>'customerId'<>row.fields->>'customerId'or engineering.fields->>'itemId'<>row.fields->>'itemId'or private.decimal(quotation.fields->>'quantity')<>private.decimal(row.fields->>'quantity')or length(coalesce(trim(row.fields->>'poDiscrepancies'),''))>0 then raise exception 'INVALID_TRANSITION';end if;
 end if;
 if row.kind='sales_order'and next_state in('closed','cancelled')then if exists(select 1 from public.stock_reservations where company_id=company and order_id=record_id and state='active')or(next_state='closed'and row.state<>'fulfilled')or(next_state='cancelled'and exists(select 1 from public.shipments where company_id=company and order_id=record_id))then raise exception 'INVALID_TRANSITION';end if;end if;
 if row.kind in('work_order','jobwork')then raise exception 'INVALID_TRANSITION: team production and jobwork execution await their invariant-owning slice';end if;
 if row.kind='ncr'and(next_state='awaiting_execution'or next_state='closed')then if length(coalesce(trim(reason),''))<3 or(next_state='closed'and length(coalesce(row.fields->>'disposition',''))=0)then raise exception 'INVALID_TRANSITION';end if;end if;
 update public.records set state=next_state,revision=revision+1 where id=record_id;
end$$;
create function private.execute_command(request jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
#variable_conflict use_variable
declare company uuid;plant uuid;actor uuid:=auth.uid();command text:=request->>'command';payload jsonb:=request->'payload';request_key uuid:=(request->>'idempotencyKey')::uuid;fingerprint text;previous private.request_results%rowtype;id uuid:=gen_random_uuid();lot public.stock_lots%rowtype;record public.records%rowtype;reservation public.stock_reservations%rowtype;package public.packages%rowtype;shipment public.shipments%rowtype;inspection public.inspections%rowtype;quantity numeric;total numeric;required_permission text;next_state text;passed boolean;value text;result jsonb;error_code text;
begin
 if request->>'contractVersion'<>'1'or request->'authority'->>'kind'<>'team'or jsonb_typeof(payload)<>'object'or octet_length(request::text)>150000 then raise exception 'INVALID_INPUT';end if;
 company:=(request->'authority'->>'companyId')::uuid;
 plant:=coalesce((request->'authority'->>'plantId')::uuid,(select p.id from public.plants p join public.memberships m on m.company_id=p.company_id where p.company_id=company and m.user_id=actor and m.active and(m.all_plants or exists(select 1 from public.member_plant_scopes s where s.company_id=company and s.user_id=actor and s.plant_id=p.id))order by p.id limit 1));
 required_permission:=private.command_permission(command,payload);if required_permission='UNIMPLEMENTED'then raise exception 'INVALID_TRANSITION: command is not implemented in team authority';end if;
 perform private.require_permission(company,required_permission,plant);if plant is null then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
 perform pg_advisory_xact_lock(hashtextextended(company::text||plant::text,0));
 fingerprint:=encode(extensions.digest(jsonb_build_object('payload',payload,'expectedRevision',request->'expectedRevision')::text,'sha256'),'hex');
 select * into previous from private.request_results rr where rr.scope=company::text||':'||plant::text and rr.actor=actor and rr.command=command and rr.request_key=request_key;
 if found then if previous.fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_KEY_REUSED';end if;return previous.result;end if;
 if payload?'quantity'then if jsonb_typeof(payload->'quantity')<>'string'then raise exception 'INVALID_INPUT';end if;quantity:=private.decimal(payload->>'quantity');if quantity<=0 then raise exception 'INVALID_INPUT';end if;end if;
 if payload?'lotId'then select * into lot from public.stock_lots where company_id=company and plant_id=plant and stock_lots.id=(payload->>'lotId')::uuid for update;if not found then raise exception 'COMPANY_SCOPE_MISMATCH';end if;if request?'expectedRevision'and request->>'expectedRevision'<>lot.revision::text then raise exception 'REVISION_CONFLICT';end if;end if;
 case command
 when 'save_record'then
  perform private.validate_fields(payload->>'kind',payload->'fields',company,plant);
  if payload?'id'then select * into record from public.records where company_id=company and plant_id=plant and records.id=(payload->>'id')::uuid for update;if not found or record.kind<>payload->>'kind'then raise exception 'COMPANY_SCOPE_MISMATCH';end if;if request?'expectedRevision'and request->>'expectedRevision'<>record.revision::text then raise exception 'REVISION_CONFLICT';end if;if(record.kind='engineering'and record.state='approved')or(record.kind in('quotation','sales_order','purchase_order','work_order')and record.state<>'draft')then raise exception 'INVALID_TRANSITION';end if;id:=record.id;update public.records set code=trim(payload->>'code'),name=trim(payload->>'name'),fields=payload->'fields',revision=revision+1 where records.id=id;
  else insert into public.records(id,company_id,plant_id,kind,code,name,state,fields)values(id,company,plant,payload->>'kind',trim(payload->>'code'),trim(payload->>'name'),case when payload->>'kind'in('customer','supplier','item')then 'active'when payload->>'kind'='equipment'then 'ready'when payload->>'kind'='ncr'then 'open'else 'draft'end,payload->'fields');end if;
  if payload->>'kind'='ncr'then update public.stock_lots set qc_state='held',revision=revision+1 where company_id=company and plant_id=plant and stock_lots.id=(payload->'fields'->>'lotId')::uuid;end if;
 when 'transition_record'then
  select * into record from public.records where company_id=company and plant_id=plant and records.id=(payload->>'id')::uuid for update;if not found then raise exception 'COMPANY_SCOPE_MISMATCH';end if;if request?'expectedRevision'and request->>'expectedRevision'<>record.revision::text then raise exception 'REVISION_CONFLICT';end if;id:=record.id;perform private.transition(company,plant,id,payload->>'state',payload->>'reason');
 when 'receive_goods'then
  select * into record from public.records where company_id=company and plant_id=plant and records.id=(payload->>'itemId')::uuid and kind='item'and state='active';if not found then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
  if payload?'purchaseOrderId'then select * into record from public.records where company_id=company and plant_id=plant and records.id=(payload->>'purchaseOrderId')::uuid and kind='purchase_order'for update;if not found or record.state not in('open','partial_receipt')or record.fields->>'itemId'<>payload->>'itemId'then raise exception 'INVALID_TRANSITION';end if;select coalesce(sum(l.quantity),0)+quantity into total from public.stock_ledger_entries l where l.company_id=company and l.plant_id=plant and l.reference_id=record.id and l.event='goods_receipt';if total>private.decimal(record.fields->>'quantity')then raise exception 'INVALID_INPUT';end if;update public.records set state=case when total=private.decimal(record.fields->>'quantity')then 'received'else 'partial_receipt'end,revision=revision+1 where records.id=record.id;end if;
  id:=private.new_lot(company,plant,(payload->>'itemId')::uuid,payload->>'location');perform private.ledger(company,plant,id,quantity,'stores',coalesce((payload->>'purchaseOrderId')::uuid,id),'goods_receipt');
 when 'record_inspection'then
  select * into record from public.records where company_id=company and plant_id=plant and records.id=lot.item_id;
  if payload->>'unit'<>record.fields->>'unit'then raise exception 'UNIT_MISMATCH';end if;
  if private.decimal(payload->>'lower')>private.decimal(payload->>'upper')or jsonb_typeof(payload->'readings')<>'array'or jsonb_array_length(payload->'readings')not between 1 and 100 then raise exception 'INVALID_INPUT';end if;passed:=true;
  for value in select jsonb_array_elements_text(payload->'readings')loop if private.decimal(value)<private.decimal(payload->>'lower')or private.decimal(value)>private.decimal(payload->>'upper')then passed:=false;end if;end loop;
  insert into public.inspections(company_id,plant_id,lot_id,lot_revision,lower_limit,upper_limit,readings,unit,passed,inspector)values(company,plant,lot.id,lot.revision+1,private.decimal(payload->>'lower'),private.decimal(payload->>'upper'),payload->'readings',payload->>'unit',passed,actor);
  id:=lot.id;update public.stock_lots set qc_state='held',revision=revision+1 where stock_lots.id=id;
 when 'release_lot'then
  select * into inspection from public.inspections where company_id=company and plant_id=plant and lot_id=lot.id order by created_at desc,id desc limit 1;
  if not found or not inspection.passed or inspection.lot_revision<>lot.revision then raise exception 'INSPECTION_REQUIRED';end if;
  if inspection.inspector=actor and(select independent_review from public.companies where companies.id=company)then raise exception 'INDEPENDENT_REVIEW_REQUIRED';end if;
  if exists(select 1 from public.records where company_id=company and plant_id=plant and kind='ncr'and state<>'closed'and fields->>'lotId'=lot.id::text)then raise exception 'LOT_QC_HOLD';end if;
  id:=lot.id;update public.stock_lots set qc_state='released',revision=revision+1 where stock_lots.id=id;
 when 'hold_lot'then if length(trim(coalesce(payload->>'reason','')))<3 then raise exception 'INVALID_INPUT';end if;id:=lot.id;update public.stock_lots set qc_state='held',revision=revision+1 where stock_lots.id=id;
 when 'reserve_stock'then
  if lot.qc_state<>'released'then raise exception 'LOT_QC_HOLD';end if;if quantity>private.balance(company,plant,lot.id)-private.reserved(company,plant,lot.id)then raise exception 'INSUFFICIENT_AVAILABLE_STOCK';end if;
  select * into record from public.records where company_id=company and plant_id=plant and records.id=(payload->>'orderId')::uuid and kind='sales_order'for update;if not found or record.state not in('accepted','partially_fulfilled')or record.fields->>'itemId'<>lot.item_id::text then raise exception 'INVALID_TRANSITION';end if;
  select coalesce(sum(r.quantity),0)+quantity into total from public.stock_reservations r where r.company_id=company and r.plant_id=plant and r.order_id=record.id and r.state in('active','dispatched');if total>private.decimal(record.fields->>'quantity')then raise exception 'INVALID_INPUT';end if;
  insert into public.stock_reservations(id,company_id,plant_id,lot_id,order_id,quantity)values(id,company,plant,lot.id,record.id,quantity);update public.stock_lots set revision=revision+1 where stock_lots.id=lot.id;
 when 'release_reservation'then
  select * into reservation from public.stock_reservations where company_id=company and plant_id=plant and stock_reservations.id=(payload->>'reservationId')::uuid for update;if not found or reservation.state<>'active'or exists(select 1 from public.packages where company_id=company and reservation_id=reservation.id)then raise exception 'INVALID_TRANSITION';end if;id:=reservation.id;update public.stock_reservations set state='released'where stock_reservations.id=id;
 when 'verify_packing'then
  select * into reservation from public.stock_reservations where company_id=company and plant_id=plant and stock_reservations.id=(payload->>'reservationId')::uuid for update;if not found or reservation.state<>'active'then raise exception 'INVALID_TRANSITION';end if;select * into lot from public.stock_lots where company_id=company and plant_id=plant and stock_lots.id=reservation.lot_id for update;
  if lot.qc_state<>'released'then raise exception 'LOT_QC_HOLD';end if;if payload->>'scannedLotCode'<>lot.code or quantity<>reservation.quantity then raise exception 'INVALID_INPUT';end if;
  insert into public.packages(id,company_id,plant_id,code,reservation_id,lot_id,order_id,quantity)values(id,company,plant,'PKG-'||upper(substr(id::text,1,8)),reservation.id,lot.id,reservation.order_id,quantity);
 when 'confirm_dispatch'then
  select * into package from public.packages where company_id=company and plant_id=plant and packages.id=(payload->>'packageId')::uuid for update;if not found or package.state<>'verified'then raise exception 'INVALID_TRANSITION';end if;
  select * into lot from public.stock_lots where company_id=company and plant_id=plant and stock_lots.id=package.lot_id for update;if lot.qc_state<>'released'then raise exception 'LOT_QC_HOLD';end if;
  select * into reservation from public.stock_reservations where company_id=company and plant_id=plant and stock_reservations.id=package.reservation_id for update;if reservation.state<>'active'then raise exception 'INVALID_TRANSITION';end if;
  select * into record from public.records where company_id=company and plant_id=plant and records.id=package.order_id for update;if record.state not in('accepted','partially_fulfilled')then raise exception 'INVALID_TRANSITION';end if;
  if package.quantity>private.balance(company,plant,lot.id)then raise exception 'INSUFFICIENT_AVAILABLE_STOCK';end if;
  select coalesce(sum(s.quantity),0)+package.quantity into total from public.shipments s where s.company_id=company and s.plant_id=plant and s.order_id=record.id;if total>private.decimal(record.fields->>'quantity')or length(trim(coalesce(payload->>'carrier','')))=0 then raise exception 'INVALID_INPUT';end if;
  perform private.ledger(company,plant,lot.id,-package.quantity,'stores',id,'dispatch');perform private.ledger(company,plant,lot.id,package.quantity,'shipped',id,'dispatch');
  insert into public.shipments(id,company_id,plant_id,code,package_id,lot_id,order_id,quantity,carrier)values(id,company,plant,'SHIP-'||upper(substr(id::text,1,8)),package.id,lot.id,record.id,package.quantity,payload->>'carrier');update public.packages set state='dispatched'where packages.id=package.id;update public.stock_reservations set state='dispatched'where stock_reservations.id=reservation.id;update public.records set state=case when total=private.decimal(record.fields->>'quantity')then 'fulfilled'else 'partially_fulfilled'end,revision=revision+1 where records.id=record.id;update public.stock_lots set revision=revision+1 where stock_lots.id=lot.id;
 when 'receive_customer_return'then
  select * into shipment from public.shipments where company_id=company and plant_id=plant and shipments.id=(payload->>'shipmentId')::uuid for update;if not found then raise exception 'COMPANY_SCOPE_MISMATCH';end if;
  select coalesce(sum(l.quantity),0)+quantity into total from public.stock_ledger_entries l where l.company_id=company and l.plant_id=plant and l.reference_id=shipment.id and l.event='customer_return';if total>shipment.quantity or length(trim(coalesce(payload->>'reason','')))<3 then raise exception 'INVALID_INPUT';end if;select * into lot from public.stock_lots where company_id=company and plant_id=plant and stock_lots.id=shipment.lot_id;id:=private.new_lot(company,plant,lot.item_id,lot.location);perform private.ledger(company,plant,id,quantity,'stores',shipment.id,'customer_return');perform private.ledger(company,plant,lot.id,-quantity,'shipped',shipment.id,'customer_return_custody');
 else raise exception 'INVALID_INPUT';end case;
 perform private.audit(company,plant,command,id,coalesce(payload->>'reason',''));
 result:=jsonb_build_object('ok',true,'value',jsonb_build_object('id',id,'message','Committed to company PostgreSQL.'),'committedAt',now(),'authority',request->'authority');
 insert into private.request_results(scope,actor,command,request_key,fingerprint,result)values(company::text||':'||plant::text,actor,command,request_key,fingerprint,result);return result;
exception when others then
 error_code:=split_part(sqlerrm,':',1);if error_code not in('AUTH_REQUIRED','PERMISSION_DENIED','COMPANY_SCOPE_MISMATCH','INVALID_INPUT','INVALID_TRANSITION','REVISION_CONFLICT','IDEMPOTENCY_KEY_REUSED','INSUFFICIENT_AVAILABLE_STOCK','LOT_QC_HOLD','UNIT_MISMATCH','INSPECTION_REQUIRED','INDEPENDENT_REVIEW_REQUIRED')then error_code:='INVALID_INPUT';end if;
 return jsonb_build_object('ok',false,'error',jsonb_build_object('code',error_code,'message','Command rejected by current authority rules.','retryable',false,'correlationId',coalesce(request->>'idempotencyKey',gen_random_uuid()::text)));
end$$;
create function public.execute_command(request jsonb)returns jsonb language sql security invoker set search_path=''as $$select private.execute_command(request)$$;

create function public.workspace_snapshot(authority jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare company uuid:=(authority->>'companyId')::uuid;plant uuid;metadata jsonb;records jsonb;lots jsonb;reservations jsonb;packages jsonb;shipments jsonb;audit jsonb;capabilities jsonb;
begin
 if authority->>'kind'<>'team'or not private.member(company)then raise exception 'PERMISSION_DENIED';end if;
 plant:=coalesce((authority->>'plantId')::uuid,(select id from public.plants where company_id=company order by id limit 1));if plant is null or not private.member(company,plant)then raise exception 'PERMISSION_DENIED';end if;
 select jsonb_build_object('id',id,'name',name,'currency',currency,'timezone',timezone,'createdAt',created_at)into metadata from public.companies where id=company;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'kind',r.kind,'code',r.code,'name',r.name,'state',r.state,'revision',r.revision::text,'fields',r.fields,'createdAt',r.created_at)),'[]')into records from(select * from public.records where company_id=company and plant_id=plant order by created_at desc,id limit 200)r;
 select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'code',l.code,'itemId',l.item_id,'itemName',coalesce(r.name,'Restricted item'),'unit',coalesce(r.fields->>'unit',''),'location',l.location,'qcState',l.qc_state,'revision',l.revision::text,'onHand',private.decimal_text(coalesce((select sum(quantity)from public.stock_ledger_entries where company_id=company and plant_id=plant and lot_id=l.id and custody='stores'),0)),'reserved',private.decimal_text(coalesce((select sum(quantity)from public.stock_reservations where company_id=company and plant_id=plant and lot_id=l.id and state='active'),0)),'available',case when l.qc_state='held'then '0'else private.decimal_text(coalesce((select sum(quantity)from public.stock_ledger_entries where company_id=company and plant_id=plant and lot_id=l.id and custody='stores'),0)-coalesce((select sum(quantity)from public.stock_reservations where company_id=company and plant_id=plant and lot_id=l.id and state='active'),0))end,'wip',private.decimal_text(coalesce((select sum(quantity)from public.stock_ledger_entries where company_id=company and plant_id=plant and lot_id=l.id and custody='wip'),0)),'vendor',private.decimal_text(coalesce((select sum(quantity)from public.stock_ledger_entries where company_id=company and plant_id=plant and lot_id=l.id and custody='vendor'),0)))),'[]')into lots from(select * from public.stock_lots where company_id=company and plant_id=plant order by code desc limit 200)l left join public.records r on r.id=l.item_id and r.company_id=l.company_id;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'lotId',r.lot_id,'orderId',r.order_id,'quantity',private.decimal_text(r.quantity),'state',r.state)),'[]')into reservations from(select * from public.stock_reservations where company_id=company and plant_id=plant order by id limit 200)r;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'lotId',p.lot_id,'orderId',p.order_id,'quantity',private.decimal_text(p.quantity),'state',p.state)),'[]')into packages from(select * from public.packages where company_id=company and plant_id=plant order by code desc limit 200)p;
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'code',s.code,'lotId',s.lot_id,'orderId',s.order_id,'quantity',private.decimal_text(s.quantity),'carrier',s.carrier,'createdAt',s.created_at)),'[]')into shipments from(select * from public.shipments where company_id=company and plant_id=plant order by created_at desc limit 200)s;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'command',a.command,'entityId',a.entity_id,'actor',a.actor::text,'reason',a.reason,'createdAt',a.created_at)),'[]')into audit from(select * from public.audit_log where company_id=company and(plant_id=plant or plant_id is null)order by created_at desc limit 100)a;
 select coalesce(jsonb_agg(permission),'[]')into capabilities from(select distinct p.permission from public.member_role_assignments a join public.role_permissions p on p.company_id=a.company_id and p.role_name=a.role_name where a.company_id=company and a.user_id=auth.uid())p;
 return jsonb_build_object('workspace',metadata,'records',records,'lots',lots,'reservations',reservations,'packages',packages,'shipments',shipments,'audit',audit,'capabilities',capabilities,'asOf',now());
end$$;
revoke all on function private.validate_fields(text,jsonb,uuid,uuid),private.command_permission(text,jsonb),private.new_lot(uuid,uuid,uuid,text),private.ledger(uuid,uuid,uuid,numeric,text,uuid,text),private.transition(uuid,uuid,uuid,text,text),private.execute_command(jsonb)from public,anon,authenticated;
grant execute on function private.execute_command(jsonb),private.decimal_text(numeric)to authenticated;
revoke all on function public.execute_command(jsonb),public.workspace_snapshot(jsonb)from public,anon;
grant execute on function public.execute_command(jsonb),public.workspace_snapshot(jsonb)to authenticated;
